use super::*;

/// What the inbox report says, so the caller does not assemble prose itself.
pub fn render(files: &[InboxFile]) -> String {
    if files.is_empty() {
        return "nothing waiting\n".to_string();
    }
    let mut out = format!("{} file(s) waiting\n", files.len());
    for f in files {
        match f.institution {
            Some(id) => out.push_str(&format!("  {} · {} · {} bytes\n", f.name, id, f.bytes)),
            // Named, not silently skipped: the wrong profile reads a date as an amount and says so
            // confidently, so an unreadable name is a thing to go and fix rather than to ignore.
            None => out.push_str(&format!(
                "  {} · UNREADABLE — rename it to start with one of: {}\n",
                f.name,
                KNOWN.join(", ")
            )),
        }
    }
    out
}
